from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Count how many subarrays of length k each number appears in
        freq = [0] * 51  # nums[i] <= 50

        for start in range(n - k + 1):
            sub = nums[start:start + k]
            unique_nums = set(sub)          # avoid double counting within the same subarray
            for num in unique_nums:
                freq[num] += 1

        # Find the largest number that appears in exactly one subarray
        for num in range(50, -1, -1):
            if freq[num] == 1:
                return num
        return -1
