from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10**15
        # dp[i][j][k] = max profit reaching (i,j) having used k neutralizations
        dp = [[[NEG_INF]*3 for _ in range(n)] for _ in range(m)]

        # initialize (0,0)
        v0 = coins[0][0]
        # no neutralization
        dp[0][0][0] = v0
        # use one neutralization if v0 is negative
        if v0 < 0:
            dp[0][0][1] = 0
        # cannot have 2 neutralizations at start

        # first row
        for j in range(1, n):
            v = coins[0][j]
            for k in range(3):
                if dp[0][j-1][k] == NEG_INF:
                    continue
                # without neutralization
                dp[0][j][k] = max(dp[0][j][k], dp[0][j-1][k] + v)
                # with neutralization if possible
                if k < 2 and v < 0:
                    dp[0][j][k+1] = max(dp[0][j][k+1], dp[0][j-1][k])

        # first column
        for i in range(1, m):
            v = coins[i][0]
            for k in range(3):
                if dp[i-1][0][k] == NEG_INF:
                    continue
                dp[i][0][k] = max(dp[i][0][k], dp[i-1][0][k] + v)
                if k < 2 and v < 0:
                    dp[i][0][k+1] = max(dp[i][0][k+1], dp[i-1][0][k])

        # rest of grid
        for i in range(1, m):
            for j in range(1, n):
                v = coins[i][j]
                for k in range(3):
                    # from top
                    if dp[i-1][j][k] != NEG_INF:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + v)
                        if k < 2 and v < 0:
                            dp[i][j][k+1] = max(dp[i][j][k+1], dp[i-1][j][k])
                    # from left
                    if dp[i][j-1][k] != NEG_INF:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + v)
                        if k < 2 and v < 0:
                            dp[i][j][k+1] = max(dp[i][j][k+1], dp[i][j-1][k])

        return max(dp[m-1][n-1])
