class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        """
        Returns the length of the longest palindrome that can be formed by
        concatenating a substring of `s` (possibly empty) with a substring of
        `t` (possibly empty).
        """
        def substrings(st: str):
            """Generate all substrings of st, including the empty string."""
            n = len(st)
            res = [""]
            for i in range(n):
                for j in range(i, n):
                    res.append(st[i:j+1])
            return res

        sub_s = substrings(s)
        sub_t = substrings(t)

        max_len = 0
        for a in sub_s:
            for b in sub_t:
                cand = a + b
                if cand == cand[::-1]:
                    max_len = max(max_len, len(cand))
        return max_len
