from typing import List
import math

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        """
        For each group value g, find the smallest index j such that g % elements[j] == 0.
        If none exists, assign -1.
        """
        # Map each element value to the smallest index that has that value
        min_index_for_value = {}
        for idx, val in enumerate(elements):
            if val not in min_index_for_value or idx < min_index_for_value[val]:
                min_index_for_value[val] = idx

        result = []
        for g in groups:
            best = -1
            limit = int(math.isqrt(g))
            for d in range(1, limit + 1):
                if g % d != 0:
                    continue
                # divisor d
                if d in min_index_for_value:
                    cand = min_index_for_value[d]
                    if best == -1 or cand < best:
                        best = cand
                # paired divisor g//d
                d2 = g // d
                if d2 != d and d2 in min_index_for_value:
                    cand = min_index_for_value[d2]
                    if best == -1 or cand < best:
                        best = cand
            result.append(best)
        return result
