from typing import List, Tuple

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Priority mapping: REACTIVATE < OFFLINE < MESSAGE
        PRIORITY = {"REACTIVATE": 0, "OFFLINE": 1, "MESSAGE": 2}
        processed: List[Tuple[int, int, Tuple[str, str]]] = []

        for ev in events:
            typ, ts_str, data = ev
            ts = int(ts_str)
            if typ == "OFFLINE":
                user_id = int(data)
                processed.append((ts, PRIORITY["OFFLINE"], ("OFFLINE", str(user_id))))
                # schedule reactivation
                rets = ts + 60
                processed.append((rets, PRIORITY["REACTIVATE"], ("REACTIVATE", str(user_id))))
            else:  # MESSAGE
                processed.append((ts, PRIORITY["MESSAGE"], ("MESSAGE", data)))

        # Sort by timestamp, then priority
        processed.sort(key=lambda x: (x[0], x[1]))

        online = [True] * numberOfUsers
        mentions = [0] * numberOfUsers

        for ts, _, (etype, payload) in processed:
            if etype == "REACTIVATE":
                uid = int(payload)
                online[uid] = True
            elif etype == "OFFLINE":
                uid = int(payload)
                online[uid] = False
            else:  # MESSAGE
                mentions_str = payload
                tokens = mentions_str.split()
                if len(tokens) == 1 and tokens[0] == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif len(tokens) == 1 and tokens[0] == "HERE":
                    for uid in range(numberOfUsers):
                        if online[uid]:
                            mentions[uid] += 1
                else:
                    for token in tokens:
                        if token.startswith("id"):
                            uid = int(token[2:])
                            if 0 <= uid < numberOfUsers:
                                mentions[uid] += 1
        return mentions
